<?php
// Personal transaction ledger.
declare(strict_types=1);
require_once __DIR__ . '/includes/config.php'; require_once __DIR__ . '/includes/database.php'; require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/csrf.php'; require_once __DIR__ . '/includes/functions.php'; require_once __DIR__ . '/includes/external_api.php';
require_auth(); $user=current_user(); $userId=(int)$user['id']; $message=flash('success'); $error=flash('error'); $autoReference='TXN-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,5));
$highlightIds=array_values(array_unique(array_filter(array_map('intval',explode(',',(string)($_GET['highlight']??''))),static fn($v)=>$v>0))); $highlightIds=array_slice($highlightIds,0,50); $typeFilter=in_array((string)($_GET['type']??''),['income','expense'],true)?(string)$_GET['type']:'all';
$categories=[]; $budgets=[]; $transactions=[]; $totalIncome=0.0; $totalExpenses=0.0; $runningBalance=(float)($user['opening_balance'] ?? 0);
$convertAmount=filter_var($_GET['convert_amount']??null,FILTER_VALIDATE_FLOAT); $convertFrom=strtoupper((string)($_GET['convert_from']??'ZAR')); $convertTo=strtoupper((string)($_GET['convert_to']??'USD')); $convertRate=null; $convertDate=null; $convertError=null; if($_GET['convert']??false){ if(!preg_match('/^[A-Z]{3}$/',$convertFrom))$convertFrom='ZAR'; if(!preg_match('/^[A-Z]{3}$/',$convertTo))$convertTo='USD'; if($convertAmount===false||$convertAmount===null||$convertAmount<0)$convertError='Enter an amount to convert.'; elseif($convertFrom===$convertTo){$convertRate=1.0;$convertDate=date('Y-m-d');} else {$fx=external_json_get('https://api.frankfurter.dev/v2/rate/'.strtolower($convertFrom).'/'.strtolower($convertTo),86400,'frankfurter-'.$convertFrom.'-'.$convertTo); if($fx['ok']&&isset($fx['data']['rate'])){$convertRate=(float)$fx['data']['rate'];$convertDate=(string)($fx['data']['date']??'');}else $convertError=$fx['error']??'Reference rate unavailable.';}}
if (request_method_is('POST')) { require_csrf(); $action=(string)($_POST['action'] ?? ''); if ($action==='delete' && database_ready()) { $q=db()->prepare('UPDATE transactions SET deleted_at=CURRENT_TIMESTAMP WHERE id=:id AND user_id=:u AND deleted_at IS NULL'); $q->execute(['id'=>(int)($_POST['id'] ?? 0),'u'=>$userId]); if ($q->rowCount()) { record_audit_event($userId, 'transaction.deleted', 'transaction', (int)($_POST['id'] ?? 0), ['reason'=>'user_requested']); if (function_exists('invalidate_financial_records_cache')) invalidate_financial_records_cache($userId); $message='Transaction removed.'; } else $error='That transaction could not be found.'; } elseif ($action==='create' && database_ready()) { $type=(string)($_POST['transaction_type'] ?? 'expense'); $amount=parse_money_input($_POST['amount'] ?? 0); $date=(string)($_POST['transaction_date'] ?? date('Y-m-d')); $description=trim((string)($_POST['description'] ?? '')); $ref=trim((string)($_POST['system_reference'] ?? '')); if ($ref==='' || !str_starts_with($ref,'TXN-')) $ref=$autoReference; if (!in_array($type,['income','expense','transfer'],true) || $amount<=0 || ($date=normalize_transaction_date($date))===null || $description==='') $error='Please enter a valid type, a positive amount, a real date (not in the future) and a description.'; else { try { $q=db()->prepare('INSERT INTO transactions (user_id,category_id,budget_id,transaction_type,amount,transaction_date,description,payment_method,reference_code) VALUES (:u,:category,:budget,:type,:amount,:date,:description,:method,:reference)'); $q->execute(['u'=>$userId,'category'=>((int)($_POST['category_id'] ?? 0)) ?: null,'budget'=>((int)($_POST['budget_id'] ?? 0)) ?: null,'type'=>$type,'amount'=>$amount,'date'=>$date,'description'=>$description,'method'=>trim((string)($_POST['payment_method'] ?? '')) ?: 'EFT / Card','reference'=>$ref]); $transactionId=(int)db()->lastInsertId(); record_audit_event($userId, 'transaction.created', 'transaction', $transactionId, ['type'=>$type,'amount'=>$amount,'transaction_date'=>$date,'reference_code'=>$ref]); if (function_exists('invalidate_financial_records_cache')) invalidate_financial_records_cache($userId); flash('success',ucfirst($type).' of '.money($amount).' successfully recorded.'); redirect_to('transactions.php'); } catch (Throwable $e) { $error=app_error_message($e); } } } }
if (database_ready()) { try { require_once __DIR__ . '/includes/categories_service.php'; $categories=category_list(db(),$userId); $q=db()->prepare("SELECT b.id,b.name,b.amount,COALESCE(SUM(t.amount),0) current_spent FROM budgets b LEFT JOIN transactions t ON t.budget_id=b.id AND t.user_id=b.user_id AND t.deleted_at IS NULL AND t.transaction_type='expense' AND t.transaction_date BETWEEN b.period_start AND b.period_end WHERE b.user_id=:u GROUP BY b.id,b.name,b.amount ORDER BY b.name"); $q->execute(['u'=>$userId]); $budgets=$q->fetchAll(); $q=db()->prepare('SELECT t.id,t.transaction_date,t.description,t.transaction_type,t.amount,t.payment_method,t.reference_code,b.name budget_name,c.name category_name FROM transactions t LEFT JOIN budgets b ON b.id=t.budget_id LEFT JOIN expense_categories c ON c.id=t.category_id WHERE t.user_id=:u AND t.deleted_at IS NULL ORDER BY t.transaction_date DESC,t.id DESC LIMIT 300'); $q->execute(['u'=>$userId]); $transactions=$q->fetchAll(); if($highlightIds){ $have=array_map(static fn($r)=>(int)$r['id'],$transactions); $missing=array_values(array_diff($highlightIds,$have)); if($missing){ $in=implode(',',array_map('intval',$missing)); $q=db()->prepare("SELECT t.id,t.transaction_date,t.description,t.transaction_type,t.amount,t.payment_method,t.reference_code,b.name budget_name,c.name category_name FROM transactions t LEFT JOIN budgets b ON b.id=t.budget_id LEFT JOIN expense_categories c ON c.id=t.category_id WHERE t.user_id=:u AND t.deleted_at IS NULL AND t.id IN ($in)"); $q->execute(['u'=>$userId]); $transactions=array_merge($q->fetchAll(),$transactions); usort($transactions,static fn($a,$b)=>[$b['transaction_date'],$b['id']]<=>[$a['transaction_date'],$a['id']]); } } $q=db()->prepare("SELECT transaction_type,COALESCE(SUM(amount),0) total FROM transactions WHERE user_id=:u AND deleted_at IS NULL AND transaction_type IN ('income','expense') GROUP BY transaction_type"); $q->execute(['u'=>$userId]); foreach ($q->fetchAll() as $row) { if ($row['transaction_type']==='income') $totalIncome=(float)$row['total']; else $totalExpenses=(float)$row['total']; } $runningBalance += $totalIncome-$totalExpenses; } catch (Throwable $e) { $error=app_error_message($e); } }
$showForm=($_GET['action'] ?? '')==='add' || (request_method_is('POST') && ($_POST['action'] ?? '')==='create'); $page_title=t('nav_transactions'); require __DIR__ . '/includes/header.php';
?>
<div class="page-heading"><div><div class="ledger-line"></div><span class="eyebrow">PERSONAL MONEY RECORD</span><h1><?= e(t('nav_transactions')) ?></h1><p>A clear, private ledger for every rand that comes in or goes out.</p></div><div class="page-heading__actions"><button type="button" id="btn-toggle-form" class="btn btn--accent">+ Record money</button></div></div>
<?php if ($highlightIds): ?><div class="alert alert--success">Showing the transaction<?= count($highlightIds)>1?'s':'' ?> just recorded from your scanned document (highlighted below). <a href="transactions.php">Show all records</a> · <a href="transactions.php?type=income">Income only</a> · <a href="transactions.php?type=expense">Expenses only</a></div><?php endif; ?><?php if ($message): ?><div class="alert alert--success" data-auto-dismiss><?= e($message) ?></div><?php endif; ?><?php if ($error): ?><div class="alert alert--error"><?= e($error) ?></div><?php endif; ?>
<section class="stat-grid" style="margin-bottom:24px;"><div class="stat-card stat-card--mint"><span class="stat-card__label">Total Income</span><strong class="stat-card__value">+<?= money($totalIncome) ?></strong><span class="stat-card__note">All recorded income</span></div><div class="stat-card stat-card--rose"><span class="stat-card__label">Total Expenses</span><strong class="stat-card__value"><?= money($totalExpenses) ?></strong><span class="stat-card__note">All recorded personal expenses</span></div><div class="stat-card"><span class="stat-card__label">Net Movement</span><strong class="stat-card__value <?= $totalIncome-$totalExpenses>=0?'amount-positive':'amount-negative' ?>"><?= money($totalIncome-$totalExpenses) ?></strong><span class="stat-card__note">Income minus expenses</span></div><div class="stat-card"><span class="stat-card__label">Current Balance</span><strong class="stat-card__value"><?= money($runningBalance) ?></strong><span class="stat-card__note">Opening balance plus activity</span></div></section>
<section id="record-transaction-panel" class="panel" style="margin-bottom:24px;border:2px solid var(--marigold);<?= $showForm?'':'display:none;' ?>"><div class="panel__heading"><div><h2>Record money in or out</h2><p>Your reference is generated automatically.</p></div><button type="button" id="btn-close-form" class="panel__link" style="background:none;border:0;cursor:pointer;">Close ×</button></div><form method="post" class="form-grid" data-validate><input type="hidden" name="action" value="create"><?= csrf_field() ?><div class="auth-form__grid auth-form__grid--two"><div class="form-field"><label for="transaction_type">Transaction type</label><select id="transaction_type" name="transaction_type"><option value="expense">Expense (money out)</option><option value="income" <?= ($_GET['type'] ?? '')==='income'?'selected':'' ?>>Income (money in)</option><option value="transfer">Transfer</option></select></div><div class="form-field"><label for="amount">Amount (ZAR)</label><input id="amount" name="amount" type="number" min="0.01" step="0.01" required placeholder="e.g. 450.00"></div><div class="form-field"><label for="transaction_date">Date</label><input id="transaction_date" name="transaction_date" type="date" value="<?= date('Y-m-d') ?>" required></div><div class="form-field"><label for="category_id">Category</label><select id="category_id" name="category_id"><option value="0">General</option><?php foreach ($categories as $category): ?><option value="<?= (int)$category['id'] ?>"><?= e((string)$category['name']) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="budget_id">Link to a budget <span class="subtle">Optional</span></label><select id="budget_id" name="budget_id"><option value="">No linked budget</option><?php foreach ($budgets as $budget): ?><option value="<?= (int)$budget['id'] ?>"><?= e((string)$budget['name']) ?> · <?= money((float)$budget['amount']-min((float)$budget['amount'],(float)$budget['current_spent'])) ?> left</option><?php endforeach; ?></select></div><div class="form-field"><label for="payment_method">Payment method</label><input id="payment_method" name="payment_method" list="methods-list" placeholder="EFT, Card, Cash" value="EFT"><datalist id="methods-list"><option value="EFT"><option value="Debit Card"><option value="Cash"><option value="Instant Pay"></datalist></div></div><div class="form-field"><label for="description">Description</label><input id="description" name="description" required maxlength="255" placeholder="e.g. Weekly groceries"></div><div class="form-field"><label>Reference code</label><input type="text" value="<?= e($autoReference) ?>" readonly disabled style="font-family:monospace;font-weight:700;"><input type="hidden" name="system_reference" value="<?= e($autoReference) ?>"></div><button class="btn btn--primary" type="submit" style="margin-top:14px;width:100%;justify-content:center;">Save transaction <span>✓</span></button></form></section>
</section>\n<section class="panel compact-tool" style="margin:18px 0;border-left:3px solid var(--marigold);"><div class="panel__heading"><div><h2>Quick currency check</h2><p>A small planning aid for travel, remittances, or online purchases. It does not exchange money.</p></div><span class="badge">Reference rate</span></div><form method="get" class="auth-form__grid auth-form__grid--two"><input type="hidden" name="convert" value="1"><div class="form-field"><label for="convert_amount">Amount</label><input id="convert_amount" name="convert_amount" type="number" min="0" step="0.01" value="<?= $convertAmount!==false&&$convertAmount!==null?e((string)$convertAmount):'' ?>" placeholder="e.g. 100"></div><div class="form-field"><label for="convert_from">From</label><input id="convert_from" name="convert_from" maxlength="3" value="<?=e($convertFrom)?>"></div><div class="form-field"><label for="convert_to">To</label><input id="convert_to" name="convert_to" maxlength="3" value="<?=e($convertTo)?>"></div><div><button class="btn btn--quiet" type="submit">Check rate</button></div></form><?php if($convertError):?><div class="alert alert--error" style="margin-top:12px"><?=e($convertError)?></div><?php elseif($convertRate!==null&&$convertAmount!==false&&$convertAmount!==null):?><p class="compact-tool__result"><strong><?=e(number_format((float)$convertAmount,2,'.',','))?> <?=e($convertFrom)?> = <?=e(number_format((float)$convertAmount*$convertRate,2,'.',','))?> <?=e($convertTo)?></strong><span>Rate <?=e(number_format($convertRate,6,'.',','))?> · <?=e($convertDate?:'today')?></span></p><?php endif;?></section>
<section class="panel"><div class="panel__heading"><div><h2><?= e(t('recent_activity')) ?></h2><p><?= count($transactions) ?> personal records captured</p></div><div class="tx-filter" style="display:flex;gap:6px;margin-right:auto;margin-left:16px"><button type="button" class="btn btn--quiet" data-tx-filter="all">All</button><button type="button" class="btn btn--quiet" data-tx-filter="income">Income</button><button type="button" class="btn btn--quiet" data-tx-filter="expense">Expenses</button></div><input type="text" id="tx-search-input" placeholder="Search description or reference" style="padding:6px 12px;font-size:13px;border-radius:8px;border:1px solid var(--line);width:240px;"></div><?php if (!$transactions): ?><div class="empty-state"><div class="empty-state__mark">◌</div><h3><?= e(t('no_transactions')) ?></h3><p>Record your first transaction to start building a clear money picture.</p></div><?php else: ?><div class="table-wrap"><table class="data-table" id="transactions-table"><thead><tr><th>Date</th><th>Description &amp; Reference</th><th>Category</th><th>Budget</th><th>Type</th><th>Method</th><th>Amount</th></tr></thead><tbody><?php $lastMonth=''; foreach ($transactions as $tx): $income=$tx['transaction_type']==='income'; $monthKey=substr((string)$tx['transaction_date'],0,7); if($monthKey!==$lastMonth){ $lastMonth=$monthKey; ?><tr class="tx-month"><td colspan="7" style="background:var(--paper-deep);font-weight:700;padding:8px 12px"><?= e(date('F Y',strtotime($monthKey.'-01'))) ?></td></tr><?php } ?><tr class="tx-row<?= in_array((int)$tx['id'],$highlightIds,true)?' tx-highlight':'' ?>" id="tx-<?= (int)$tx['id'] ?>" <?= in_array((int)$tx['id'],$highlightIds,true)?'style="background:var(--marigold-soft);outline:2px solid var(--marigold)"':'' ?> data-type="<?= e((string)$tx['transaction_type']) ?>"><td><?= e(safe_date((string)$tx['transaction_date'])) ?></td><td><strong><?= e((string)$tx['description']) ?></strong><?php if ($tx['reference_code']): ?><div><code style="font-size:11px;"><?= e((string)$tx['reference_code']) ?></code></div><?php endif; ?></td><td><?= $tx['category_name']?e((string)$tx['category_name']):'<span class="subtle">General</span>' ?></td><td><?= $tx['budget_name']?e((string)$tx['budget_name']):'<span class="subtle">General</span>' ?></td><td><span class="badge <?= $income?'badge--success':'badge--warning' ?>"><?= e(ucfirst((string)$tx['transaction_type'])) ?></span></td><td><?= e((string)($tx['payment_method'] ?: '—')) ?></td><td class="<?= $income?'amount-positive':'amount-negative' ?>"><?= $income?'+':'-' ?><?= money((float)$tx['amount']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<script>document.getElementById('btn-toggle-form')?.addEventListener('click',()=>{document.getElementById('record-transaction-panel').style.display='block';document.getElementById('record-transaction-panel').scrollIntoView({behavior:'smooth'});});document.getElementById('btn-close-form')?.addEventListener('click',()=>document.getElementById('record-transaction-panel').style.display='none');(function(){let f=<?= json_encode($typeFilter) ?>;const s=document.getElementById('tx-search-input');const apply=()=>{const q=(s?.value||'').toLowerCase();let any=false;const rows=[...document.querySelectorAll('#transactions-table tbody tr')];for(let i=rows.length-1;i>=0;i--){const r=rows[i];if(r.classList.contains('tx-month')){r.hidden=!any;any=false;}else{r.hidden=!((f==='all'||r.dataset.type===f)&&r.textContent.toLowerCase().includes(q));if(!r.hidden)any=true;}}};s?.addEventListener('input',apply);document.querySelectorAll('[data-tx-filter]').forEach(x=>x.style.fontWeight=x.dataset.txFilter===f?'700':'');apply();const hl=document.querySelector('.tx-highlight');if(hl)setTimeout(()=>hl.scrollIntoView({behavior:'smooth',block:'center'}),150);document.querySelectorAll('[data-tx-filter]').forEach(b=>b.addEventListener('click',()=>{f=b.dataset.txFilter;document.querySelectorAll('[data-tx-filter]').forEach(x=>x.style.fontWeight=x===b?'700':'');apply();}));})();</script>
